/// How an instruction's operand sits after its 16-bit opcode.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Layout {
    None,
    /// One byte right after the opcode.
    U8,
    /// A 2-aligned signed 16-bit offset from the end of the instruction.
    Jump,
    U16,
    /// A 4-aligned 32-bit word.
    U32,
    /// An 8-aligned 64-bit word.
    U64,
    /// A byte, then an 8-aligned 64-bit word.
    Call,
    /// A count byte, then per local a 4-aligned 32-bit hash and a byte.
    Locals,
}

impl Opcode {
    pub const fn layout(self) -> Layout {
        match self {
            Self::BitAnd
            | Self::BitOr
            | Self::BoolComplement
            | Self::BoolNot
            | Self::CastFieldObject
            | Self::CheckClearParams
            | Self::ClearArray
            | Self::ClearParams
            | Self::Dec
            | Self::DecTop
            | Self::Divide
            | Self::End
            | Self::EndSwitch
            | Self::Endon
            | Self::Equal
            | Self::EvalArray
            | Self::EvalArrayRef
            | Self::FirstArrayKey
            | Self::GetEmptyArray
            | Self::GetGame
            | Self::GetLevel
            | Self::GetLevelObject
            | Self::GetSelf
            | Self::GetSelfObject
            | Self::GetTime
            | Self::GetUndefined
            | Self::GetZero
            | Self::Greater
            | Self::GreaterEqual
            | Self::Inc
            | Self::IsDefined
            | Self::Less
            | Self::LessEqual
            | Self::Minus
            | Self::Modulus
            | Self::Multiply
            | Self::NextArrayKey
            | Self::NotEqual
            | Self::Notify
            | Self::Plus
            | Self::PreScriptCall
            | Self::Return
            | Self::Set
            | Self::ShiftLeft
            | Self::Size
            | Self::SuperEqual
            | Self::SuperNotEqual
            | Self::Vector
            | Self::VectorScale
            | Self::Wait
            | Self::WaitTill
            | Self::WaitTillFrameEnd => Layout::None,
            Self::CallMethodPtr
            | Self::CallPtr
            | Self::EvalLocal
            | Self::EvalLocalRef
            | Self::GetByte
            | Self::GetNegByte
            | Self::MethodThreadPtr
            | Self::SetWaittillVar
            | Self::ThreadPtr
            | Self::VectorConstant => Layout::U8,
            Self::Devblock
            | Self::Jump
            | Self::JumpOnFalse
            | Self::JumpOnFalseExpr
            | Self::JumpOnTrue
            | Self::JumpOnTrueExpr => Layout::Jump,
            Self::GetNegUShort | Self::GetUShort => Layout::U16,
            Self::ClearField
            | Self::EvalField
            | Self::EvalFieldRef
            | Self::EvalLevelField
            | Self::EvalLevelFieldRef
            | Self::EvalSelfField
            | Self::EvalSelfFieldRef
            | Self::GetFloat
            | Self::GetHash
            | Self::GetIString
            | Self::GetInteger
            | Self::GetString
            | Self::Switch => Layout::U32,
            Self::GetAnimation | Self::GetFunction => Layout::U64,
            Self::CallFunc | Self::CallMethod | Self::ThreadFunc | Self::ThreadMethod => {
                Layout::Call
            }
            Self::Locals => Layout::Locals,
        }
    }
}

